// Mind traps: forty cognitive biases, each with how hard it pulls, the experiment that caught it,
// and a way out. The scores are an editorial judgement, not a measurement: see POWER below.

import { lang } from '../lib/i18n';
import { localize } from '../lib/localize';

export type Family = 'belief' | 'memory' | 'social' | 'self' | 'chance' | 'value' | 'time';
export type Evidence = 'robust' | 'good' | 'debated';

export interface Trap {
  id: string;
  name: string;
  aka?: string;
  family: Family;
  /** 1–10: how hard it is to resist, even when you know it's there. */
  pull: number;
  /** 1–10: how much of everyday life it touches. */
  reach: number;
  /** 1–10: what it costs when it wins. */
  harm: number;
  evidence: Evidence;
  /** One line, the hook. */
  line: string;
  /** The thought you have when you're in it. */
  tell: string;
  what: string;
  why: string;
  study: { who: string; title: string; text: string };
  life: string[];
  escape: string[];
  fact: string;
  /** A question to try it on yourself. No answer: there's no right one, only the one most people give. */
  test?: { q: string; options: string[]; answer?: number; reveal: string };
  kin: string[];
}

export interface FamilyInfo { name: string; motto: string; hue: string; about: string }

export const FAMILIES: Record<Family, FamilyInfo> = {
  belief: { name: 'Belief', motto: 'Seeing what you expect', hue: 'fear', about: 'Once the mind has a story, it collects evidence for it and quietly files away the rest.' },
  memory: { name: 'Memory', motto: 'Rewriting the past', hue: 'sadness', about: 'Memory isn’t a recording. Every time you recall something you rebuild it, and the rebuild drifts.' },
  social: { name: 'Others', motto: 'The pull of the crowd', hue: 'love-connection', about: 'We evolved in small groups where being cast out meant death. The brain still acts like it.' },
  self: { name: 'Self', motto: 'The flattering mirror', hue: 'joy', about: 'The mind defends its picture of you like a press office: good news is yours, bad news is circumstance.' },
  chance: { name: 'Chance', motto: 'Misreading probability', hue: 'anger', about: 'Brains are built for stories, not statistics. Randomness looks like a pattern, and vivid beats likely.' },
  value: { name: 'Value', motto: 'Bad bookkeeping', hue: 'hope-interest', about: 'Worth isn’t computed, it’s felt relative to a reference point, and that point is easy to move.' },
  time: { name: 'Time', motto: 'Now over later', hue: 'calm-safety', about: 'Your future self feels like a stranger, so you keep handing them the bill.' },
};

export const EVIDENCE: Record<Evidence, [string, string]> = {
  robust: ['Robust', 'Replicated again and again, across countries and decades.'],
  good: ['Good', 'Well supported, though the size of the effect varies by setting.'],
  debated: ['Debated', 'Real in some form, but how strong it is (or why it happens) is still argued over.'],
};

/** How the power score is made: 0–100. Pull counts most, because a trap you can't step out of even knowing it's there is the dangerous kind. */
export const POWER = { pull: 4.5, reach: 3.5, harm: 2 };
export const power = (x: Trap) => Math.round(x.pull * POWER.pull + x.reach * POWER.reach + x.harm * POWER.harm);

